const input = $input.first().json;
const body = input.body || input;

const errors = [];

if (!body.recipe_id) errors.push('recipe_id');
if (!body.discord_user_id) errors.push('discord_user_id');
if (body.rating === undefined || body.rating === null) errors.push('rating');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Parametres requis manquants: ${errors.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Validate rating
const rating = parseInt(body.rating);
if (isNaN(rating) || rating < 1 || rating > 5) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'La note doit etre un entier entre 1 et 5',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    recipe_id: body.recipe_id,
    discord_user_id: body.discord_user_id,
    discord_username: body.discord_username || null,
    rating: rating
  }
}];

const apiResponse = $input.first().json;
const inputData = $('Validate Input').first().json;

const statusCode = apiResponse.statusCode || 200;
const body = apiResponse.body || apiResponse;

if (statusCode >= 400 || !body || body.detail) {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Recette '${inputData.recipe_id}' non trouvee`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

return [{
  json: {
    found: true,
    recipe_id: body.id || inputData.recipe_id,
    recipe_title: body.title || 'Recette sans titre',
    creator_discord_user_id: body.discord_user_id,
    rater_discord_user_id: inputData.discord_user_id,
    rater_username: inputData.discord_username,
    rating: inputData.rating
  }
}];

const apiResponse = $input.first().json;
const recipeData = $('Check Recipe').first().json;

const statusCode = apiResponse.statusCode || 200;
const ratingResult = apiResponse.body || apiResponse;

if (statusCode >= 400 || ratingResult.detail) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode >= 400 ? statusCode : 500,
        message: ratingResult.detail || 'Erreur lors de la creation de la note',
        status: 'API_ERROR'
      }
    }
  }];
}

// Build response
const response = {
  success: true,
  rating: {
    id: ratingResult.id,
    recipe_id: ratingResult.recipe_id || recipeData.recipe_id,
    discord_user_id: ratingResult.discord_user_id,
    rating: ratingResult.rating,
    created_at: ratingResult.created_at,
    updated_at: ratingResult.updated_at
  }
};

// Add notify if creator != rater
if (recipeData.creator_discord_user_id && 
    recipeData.creator_discord_user_id !== recipeData.rater_discord_user_id) {
  const stars = '⭐'.repeat(recipeData.rating);
  response.notify = {
    type: 'new_rating',
    to_discord_user_id: recipeData.creator_discord_user_id,
    recipe_id: recipeData.recipe_id,
    recipe_name: recipeData.recipe_title,
    from_username: recipeData.rater_username || recipeData.rater_discord_user_id,
    rating: recipeData.rating,
    stars: stars
  };
}

return [{ json: response }];
